// Selected official application controller; generated by prepare_partner_detail_window_ui.py.
namespace Zjcs.Official.PartnersUI
{
using Object = UnityEngine.Object;
using Zjcs.Official.ProfessionUI;
using Zjcs.Official.WorldUI;
using MultiLanguageText = Zjcs.Official.WorldUI.WorldMultiLanguageText;
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.UI;

public class NpcAdventureConditionContent : UIBase
{
	[SerializeField]
	private Image mMapGroupImage;

	[SerializeField]
	private Image mProfessionImage;

	[SerializeField]
	private Image mPreferenceImage;

	[SerializeField]
	private Button mMapGroupBtn;

	[SerializeField]
	private Button mProfessionBtn;

	[SerializeField]
	private Button mPreferenceBtn;

	private PartnerDetailPresentationInfo mNpcInfo;

	private PartnerDetailResourceBag mDisposableBag;



    private IPartnerDetailPresentationServices services;
    public void Configure(IPartnerDetailPresentationServices value)
    { services = value ?? throw new System.ArgumentNullException(nameof(value)); }

	private void Awake()
	{






		((UnityEvent)mMapGroupBtn.onClick).AddListener((UnityAction)OnClickMapGroupBtn);
		((UnityEvent)mProfessionBtn.onClick).AddListener((UnityAction)OnClickProfessionBtn);
		((UnityEvent)mPreferenceBtn.onClick).AddListener((UnityAction)OnClickPreferenceBtn);
	}

	protected override void OnEnableAndInited()
	{

		base.OnEnableAndInited();
		mDisposableBag = new PartnerDetailResourceBag();
		InitContent();
	}

	protected override void OnDisableAndInited()
	{
		mDisposableBag.Dispose();
		base.OnDisableAndInited();
	}

	public void Init(PartnerDetailPresentationInfo npcInfo)
	{
		InitWrapper(() =>
		{
			mNpcInfo = npcInfo;
		});
	}

	private void InitContent()
	{
		mMapGroupImage.sprite = mDisposableBag.Add(services.LoadAdventureIcon(0, mNpcInfo.MapGroupId)).Result;
        mProfessionImage.sprite = mDisposableBag.Add(services.LoadAdventureIcon(1, mNpcInfo.TravelProfession)).Result;
        mPreferenceImage.sprite = mDisposableBag.Add(services.LoadAdventureIcon(2, mNpcInfo.PreferenceGiftType)).Result;
	}

	private void OnClickMapGroupBtn()
	{
		services.PopupAdventureTip(Input.mousePosition, mNpcInfo.MapGroupId, 0, 0);
	}

	private void OnClickProfessionBtn()
	{
		services.PopupAdventureTip(Input.mousePosition, 0, mNpcInfo.TravelProfession, 0);
	}

	private void OnClickPreferenceBtn()
	{
		services.PopupAdventureTip(Input.mousePosition, 0, 0, mNpcInfo.PreferenceGiftType);
	}
}

}
